{
  "title": "迷雾中的古村",
  "scene": "夕阳余晖下，天色渐暗。你来到了一座被浓雾笼罩的古老村庄，四周静悄悄的，只有远处偶尔传来几声乌鸦的叫声。村里的房屋破败不堪，似乎已经废弃许久。几个村民神秘兮兮地交谈着，但你听不清他们在说什么，只能感觉出他们似乎在讨论什么重要的事情。",
  "goal": "找到被村民提及的‘秘密’，解开古村的谜团。",
  "choices": [
    {
      "id": "A",
      "text": "询问村民关于‘秘密’的事情",
      "outcome": "村民们害怕地躲开了你，继续小声地交谈。你没有找到任何有用的信息。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "搜索废弃的房子，看看是否有线索",
      "outcome": "在一间破旧的屋子里，你发现了一本旧日记，上面记录了关于‘秘密’的重要线索。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "跟随乌鸦的声音，看看是否有发现",
      "outcome": "你跟随乌鸦来到了村边的一座孤坟前，但坟墓已经荒废，没有发现任何线索。",
      "result": "fail",
      "next": "bad_end"
    }
  ]
}
